await tools.Create({ file_path: MD + '/validation-state.json', content: JSON.stringify(state, null, 2) + '\n' });
// --- index
const sections = c.split(/^(?=## )/m).filter(s => /^## (Area|Cross|Process)/.test(s));
const msDefault = { SKEL:'s', MAP:'m0', BOARD:'m1', HOST:'m2', CTRL:'m3', GATE:'m4', METRIC:'m5', TELEM:'m5', PROC:'final' };
const crossMs = { 'VAL-CROSS-001':'m1', 'VAL-CROSS-002':'m2–m5', 'VAL-CROSS-003':'m5', 'VAL-CROSS-004':'m3→m5', 'VAL-CROSS-005':'m4→m5', 'VAL-CROSS-006':'m1→m5', 'VAL-CROSS-007':'m1–m5', 'VAL-CROSS-008':'m1, m5', 'VAL-CROSS-009':'m1→m5' };
let idx = '# Contract index — mission `observatory-v1`\n\nGenerated from `../validation-contract.md`. One line per assertion: `ID | title | milestone | tool`.\n\n';
idx += '## Counts per prefix (drafts → contract)\n\n| Prefix | Draft | Contract |\n|---|---|---|\n';
const before = { SKEL:31, MAP:30, BOARD:42, HOST:27, CTRL:26, GATE:38, METRIC:28, TELEM:9, CROSS:16, PROC:40 };
const after = {};
for (const id of ids) { const p = id.split('-')[1]; after[p] = (after[p]||0)+1; }
let tb=0, ta=0;
for (const p of Object.keys(before)) { idx += `| VAL-${p} | ${before[p]} | ${after[p]||0} |\n`; tb += before[p]; ta += after[p]||0; }
idx += `| **Total** | **${tb}** | **${ta}** (${((1-ta/tb)*100).toFixed(1)} % fewer) |\n\n`;
for (const s of sections) {
  const head = s.split('\n')[0].slice(3);
  idx += `## ${head}\n\n`;
  for (const m of s.matchAll(/^### (VAL-([A-Z]+)-\d{3}): (.*)\n(?:[^\n]*\n)*?Tool: ([^\n]*)/gm)) {
    const id = m[1], p = m[2], title = m[3].replace(/\|/g, '\\|'), tool = m[4];
    const ms = p === 'CROSS' ? crossMs[id] : msDefault[p];
    idx += `${id} | ${title} | ${ms} | ${tool}\n`;
  }
  idx += '\n';
}
idx += inputs.decisions;
await tools.Create({ file_path: MD + '/contract-work/index.md', content: idx });
text(`state ids: ${Object.keys(state.assertions).length}; index lines with ' | ': ${idx.split('\n').filter(l=>/^VAL-/.test(l)).length}`);
